def entry (e : ℕ → P → Pair ≃ₜ Pair) (U : Set P) (r : ℕ → ℝ) (n : ℕ) :
    Set (P × Pair) :=
  {z | z.1 ∈ U ∧ euclideanPairNorm (product e n z.1 z.2) < r n}

